head.script:
/* ================= KHỞI TẠO ================= */
scwin.isMenuOpen = false;

scwin.onpageload = function() {
    dma_search.set("cateId", "ALL");
    $p.executeSubmission("sbm_getMenu");
    $p.executeSubmission("sbm_getUserInfo");
};

/* ================= HÀM DÙNG CHUNG ================= */
// Chuyển trang (đổi theo cách điều hướng của dự án nếu cần)
scwin.goPage = function(xmlPath, param) {
    var url = "/websquare/websquare.html?w2xPath=" + xmlPath;
    if (param) {
        url += "&" + param;
    }
    location.href = url;
};

// Ẩn badge khi số lượng = 0
scwin.toggleBadge = function(badge, count) {
    if (Number(count) > 0) {
        badge.show("");
    } else {
        badge.hide();
    }
};

// Hàm PUBLIC: trang khác gọi qua wfm_header.getWindow().scwin.refreshCart()
scwin.refreshCart = function() {
    if (dma_userInfo.get("isLogin") === "Y") {
        $p.executeSubmission("sbm_getCartCount");
    }
};

// Vẽ menu từ dlt_menu vào generator
scwin.renderMenu = function() {
    gen_menu.removeAll();
    var rowCnt = dlt_menu.getRowCount();
    for (var i = 0; i < rowCnt; i++) {
        var idx = gen_menu.insertChild();
        var anc = gen_menu.getChild(idx, "anc_menuItem");
        anc.setValue(dlt_menu.getCellData(i, "menuName"));
        if (dlt_menu.getCellData(i, "isHighlight") === "Y") {
            anc.addClass("es-nav__link--hot");
        }
    }
};

/* ================= SUBMISSION CALLBACK ================= */
scwin.sbm_getMenu_submitdone = function(e) {
    dlt_menu.sort("sortOrder", 0); // 0: tăng dần
    scwin.renderMenu();
};

scwin.sbm_getUserInfo_submitdone = function(e) {
    if (dma_userInfo.get("isLogin") === "Y") {
        grp_guest.hide();
        grp_member.show("flex");
        tbx_accountLabel.setValue(dma_userInfo.get("userName"));
        $p.executeSubmission("sbm_getCartCount");
    } else {
        grp_member.hide();
        grp_guest.show("flex");
        tbx_accountLabel.setValue("Tài khoản");
        dma_cartInfo.set("cartCount", 0);
        dma_cartInfo.set("wishCount", 0);
        scwin.toggleBadge(tbx_cartCount, 0);
        scwin.toggleBadge(tbx_wishCount, 0);
    }
};

scwin.sbm_getCartCount_submitdone = function(e) {
    scwin.toggleBadge(tbx_cartCount, dma_cartInfo.get("cartCount"));
    scwin.toggleBadge(tbx_wishCount, dma_cartInfo.get("wishCount"));
};

scwin.sbm_logout_submitdone = function(e) {
    dma_userInfo.setEmptyValue();
    scwin.goPage("/ui/main/index.xml");
};

scwin.sbm_common_submiterror = function(e) {
    console.error("Submission error:", e);
};

/* ================= UI EVENT ================= */
scwin.btn_menuToggle_onclick = function(e) {
    scwin.isMenuOpen = !scwin.isMenuOpen;
    if (scwin.isMenuOpen) {
        grp_nav.addClass("es-nav--open");
        btn_menuToggle.setValue("✕");
    } else {
        grp_nav.removeClass("es-nav--open");
        btn_menuToggle.setValue("☰");
    }
};

scwin.grp_logo_onclick = function(e) {
    scwin.goPage("/ui/main/index.xml");
};

scwin.ibx_keyword_onkeyup = function(e) {
    if (e.keyCode === 13) {
        scwin.btn_search_onclick();
    }
};

scwin.btn_search_onclick = function(e) {
    var keyword = (ibx_keyword.getValue() || "").trim();
    if (keyword === "") {
        alert("Vui lòng nhập từ khóa tìm kiếm.");
        ibx_keyword.focus();
        return;
    }
    var cateId = sbx_searchCate.getValue() || "ALL";
    scwin.goPage("/ui/product/search.xml",
        "keyword=" + encodeURIComponent(keyword) + "&cateId=" + cateId);
};

scwin.anc_menuItem_onclick = function(e) {
    var idx = this.getGeneratedIndex();
    var menuId = dlt_menu.getCellData(idx, "menuId");
    var menuUrl = dlt_menu.getCellData(idx, "menuUrl");
    scwin.goPage(menuUrl, "cateId=" + menuId);
};

scwin.grp_cart_onclick = function(e) {
    if (dma_userInfo.get("isLogin") !== "Y") {
        scwin.anc_login_onclick();
        return;
    }
    scwin.goPage("/ui/cart/cart.xml");
};

scwin.grp_wishlist_onclick = function(e) {
    if (dma_userInfo.get("isLogin") !== "Y") {
        scwin.anc_login_onclick();
        return;
    }
    scwin.goPage("/ui/member/wishlist.xml");
};

scwin.grp_account_onclick = function(e) {
    if (dma_userInfo.get("isLogin") === "Y") {
        scwin.goPage("/ui/member/mypage.xml");
    } else {
        scwin.anc_login_onclick();
    }
};

scwin.anc_login_onclick = function(e) {
    scwin.goPage("/ui/member/login.xml", "returnUrl=" + encodeURIComponent(location.href));
};

scwin.anc_register_onclick = function(e) {
    scwin.goPage("/ui/member/register.xml");
};

scwin.anc_logout_onclick = function(e) {
    if (confirm("Bạn có chắc muốn đăng xuất?")) {
        $p.executeSubmission("sbm_logout");
    }
};

scwin.anc_support_onclick = function(e) {
    scwin.goPage("/ui/support/faq.xml");
};

scwin.anc_trackOrder_onclick = function(e) {
    scwin.goPage("/ui/order/tracking.xml");
};
